\title[Four fields, one answer]{Four Fields, One Answer:\\ An Exact Information Law for the Splitting Types of Pure Cubics}
\author{Aristotle}
\date{September 30, 2026}

\begin{document}

\begin{abstract}
For an integer $c$ and a prime $p$, let $T_c(p)$ be the number of solutions of $x^3=c$ in $\F_p$. Empirically, over the primes $p<1000$ with $p\nmid 3c$, the normalised mutual information between $p \bmod 3$ and $T_c(p)$ equals $1.0000$ for each of the four pure cubic fields $c=2,3,5,7$. The fourth of these, $x^3-7$, has discriminant $-1323=-27\cdot 7^2$. We prove that this is a theorem valid for every $c$ and every finite sample of unramified primes. The arithmetic input is a field-level law: over any finite field $\F_q$ and for any $c\ne 0$, the equation $x^3=c$ has exactly one solution if and only if $3\nmid q-1$, and otherwise it has $0$ or $3$. Hence $T_c(p)=1$ if and only if $p\equiv 2\pmod 3$, and a single decoder, independent of $c$, recovers $p\bmod 3$ from the type. The information-theoretic input is a pinning theorem: if $f$ factors through $g$ on a finite uniform sample, then $I(f;g)=H(f)$ exactly. Together these give $I(p\bmod 3;T_c)=H(p\bmod 3)$ on every sample. The absolute value of one bit holds exactly only on residue-balanced samples and in the $S_3$ Chebotarev model, where $I(\sgn\sigma;\#\Fix\sigma)=1$. In that model $H(\#\Fix)=\tfrac23+\tfrac12\log_2 3$, so the type carries a strict surplus of $\tfrac12\log_2 3-\tfrac13>\tfrac5{12}$ bits. We also prove an exact constant-aspect $1:2$ split-to-inert count, the analogue of the field-level law for every prime exponent, and sharp counterexamples at ramified primes, for the exponent $5$, and for the non-pure cubic $x^3-x-1$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The experiment}
For $c\in\Z$ and a prime $p$ put
\[
T_c(p)=\#\{x\in\F_p : x^3=c\},
\]
the \emph{type channel} of the pure cubic $x^3-c$. A series of computational experiments measured the Shannon mutual information between $p\bmod 3$ and $T_c(p)$, for $p$ uniform among the unramified primes below $1000$. For four independent pure cubic fields $\Q(\sqrt[3]{c})$, $c\in\{2,3,5,7\}$, with discriminants $-27c^2\in\{-108,-243,-675,-1323\}$, the normalised information was $1.0000$. We explain this observation completely.

\subsection{Summary of results}
\begin{enumerate}
\item \emph{Field-level law} (Theorem~\ref{thm:field}): over every $\F_q$ and every $c\ne0$, $\#\{x^3=c\}=1\iff 3\nmid q-1$. Otherwise the count is $0$ or $3$, and $0$ means $x^3-c$ is irreducible.
\item \emph{Type-channel law} (Theorem~\ref{thm:law}): for $p\nmid 3c$, $T_c(p)=1\iff p\equiv2\pmod3$.
\item \emph{Universal decoder} (Theorem~\ref{thm:decoder}): $\delta(1)=2$, $\delta(t)=1$ for $t\ne1$, satisfies $\delta(T_c(p))=p\bmod3$ for every $c$ and every unramified $p$.
\item \emph{Pinning theorem and sample law} (Theorems~\ref{thm:pin},~\ref{thm:sample}): on every finite sample, $I(p\bmod3;T_c)=H(p\bmod3)$.
\item \emph{Exact one bit} (Theorems~\ref{thm:balanced},~\ref{thm:s3}): on balanced samples, and in the $S_3$ model.
\item \emph{Strict refinement} (Theorem~\ref{thm:gap}): $H(\#\Fix)-I=\tfrac12\log_23-\tfrac13>\tfrac5{12}$.
\item \emph{Constant-aspect Chebotarev} (Theorem~\ref{thm:const}) and \emph{every prime exponent} (Theorem~\ref{thm:kummer}), with boundaries in Section~\ref{sec:boundaries}.
\end{enumerate}

\subsection{The central correction}
The phrase ``$I(p\bmod3;T)=1.0000$ exactly'' conflates two statements. What holds on every sample is $I=H(p\bmod3)$, equivalently $I/H=1$. The absolute value $I=1$ bit holds exactly only on balanced samples and in the Chebotarev model. On the $166$ unramified primes below $1000$ for $c=7$, $H(p\bmod3)=0.99832\ldots$, and so $I=0.99832\ldots$ as well.

\section{Preliminaries}

Throughout, $S$ is a nonempty finite set with the uniform distribution, and $f:S\to B$, $g:S\to C$.

\begin{definition}[Entropy]
For $b\in B$ let $\Pr_S[f=b]=\#\{a\in S: f(a)=b\}/\#S$. With $\eta(x)=-x\log_2x$, put
\[
H_S(f)=\sum_{b\in f(S)}\eta\bigl(\Pr_S[f=b]\bigr).
\]
\end{definition}

\begin{definition}[Mutual information]
$I_S(f;g)=H_S(f)+H_S(g)-H_S\bigl((f,g)\bigr)$, where $(f,g)(a)=(f(a),g(a))$.
\end{definition}

We use that $\F_q^\times$ is cyclic of order $q-1$. For $n\ge1$ and $c\in\F_q$ put $R_n(c)=\{x\in\F_q: x^n=c\}$.

\section{The field-level law}

\begin{proposition}[Split fields]\label{prop:split}
If $c\in\F_q^\times$ and $3\mid q-1$, then $\#R_3(c)\in\{0,3\}$.
\end{proposition}
\begin{proof}
If $x_0\in R_3(c)$, then $x\mapsto x/x_0$ is a bijection $R_3(c)\to\mu_3(\F_q)$. Since $\F_q^\times$ is cyclic of order divisible by $3$, it contains exactly $3$ cube roots of unity.
\end{proof}

\begin{theorem}[Field-level type-channel law]\label{thm:field}
For every finite field $\F_q$ and every $c\ne0$, $\#R_3(c)=1\iff 3\nmid q-1$.
\end{theorem}
\begin{proof}
If $3\mid q-1$ the count is $0$ or $3$ by Proposition~\ref{prop:split}. If $3\nmid q-1$, cubing is an injective, hence bijective, endomorphism of $\F_q^\times$.
\end{proof}

The law is uniform in the characteristic. In characteristic $3$, cubing is the Frobenius automorphism.

\begin{proposition}[Inert type]\label{prop:inert}
$x^3-c$ is irreducible over $\F_q$ if and only if $R_3(c)=\emptyset$.
\end{proposition}
\begin{proof}
A cubic is reducible over a field if and only if it has a linear factor, i.e.\ a root.
\end{proof}

\section{The type-channel law over the primes}

\begin{lemma}\label{lem:unram}
If $p$ is prime and $p\nmid 3c$, then $p\bmod 3\ne0$ and $c\not\equiv0\pmod p$.
\end{lemma}

\begin{theorem}[Type-channel law]\label{thm:law}
For every $c\in\Z$ and every prime $p\nmid 3c$: $T_c(p)=1\iff p\equiv2\pmod3$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:unram}, $c\ne0$ in $\F_p$ and $p\bmod3\in\{1,2\}$. Apply Theorem~\ref{thm:field} with $q=p$.
\end{proof}

\begin{corollary}[Alphabet]\label{cor:alph}
For $p\nmid 3c$, exactly one of the following holds: $T_c(p)=1$ and $p\equiv2\pmod 3$; or $T_c(p)\in\{0,3\}$ and $p\equiv1\pmod3$.
\end{corollary}

\begin{theorem}[Universal decoder; four fields, one answer]\label{thm:decoder}
Let $\delta(1)=2$ and $\delta(t)=1$ for $t\ne1$. For every $c\in\Z$ and every prime $p\nmid 3c$, $\delta(T_c(p))=p\bmod3$. In particular, one decoder serves $c=2,3,5,7$ simultaneously.
\end{theorem}
\begin{proof}
Check the cases of Corollary~\ref{cor:alph}.
\end{proof}

\begin{corollary}[The fourth field]
For $x^3-7$ the law holds at every prime $p\notin\{3,7\}$.
\end{corollary}

\begin{example}
$T_7(5)=1$, with root $3$. $T_7(13)=0$, since the nonzero cubes mod $13$ are $\{1,5,8,12\}$. $T_7(19)=3$, with roots $4,6,9$. Since $13\equiv19\equiv1\pmod 3$ but $T_7(13)\ne T_7(19)$, the type is strictly finer than the residue.
\end{example}

