\section{A two-variable Shannon calculus}

\begin{lemma}[Locality]
If $f=f'$ on $S$, then $H_S(f)=H_S(f')$.
\end{lemma}

\begin{lemma}[Relabelling invariance]\label{lem:relabel}
If $k:C\to D$ is injective, then $H_S(k\circ g)=H_S(g)$.
\end{lemma}
\begin{proof}
$t\mapsto k(t)$ is a bijection $g(S)\to k(g(S))$ that preserves fibres, since $k(g(a))=k(t)\iff g(a)=t$.
\end{proof}

\begin{theorem}[Pinning theorem]\label{thm:pin}
If $f(a)=d(g(a))$ for all $a\in S$ and some map $d:C\to B$, then $I_S(f;g)=H_S(f)$.
\end{theorem}
\begin{proof}
On $S$, $(f,g)=k\circ g$ with $k(t)=(d(t),t)$, which is injective. So $H_S((f,g))=H_S(g)$, and the formula for $I_S$ collapses to $H_S(f)$.
\end{proof}

\begin{theorem}[Balanced binary variable]\label{thm:onebit}
If $f$ takes exactly two values $b_1\ne b_2$ on $S$, equally often, then $H_S(f)=1$.
\end{theorem}
\begin{proof}
Both probabilities equal $\tfrac12$, so $H_S(f)=2\cdot\tfrac12\log_22=1$.
\end{proof}

\section{The sample law}

\begin{theorem}[Sample law]\label{thm:sample}
For every $c\in\Z$ and every finite set $S$ of primes not dividing $3c$,
\[
I_S(p\bmod3;\,T_c)=H_S(p\bmod3).
\]
\end{theorem}
\begin{proof}
Theorem~\ref{thm:decoder} gives $p\bmod 3=\delta(T_c(p))$ on $S$. Apply Theorem~\ref{thm:pin}.
\end{proof}

\begin{theorem}[Balanced samples]\label{thm:balanced}
If moreover $S\ne\emptyset$ has equally many primes $\equiv1$ and $\equiv2\pmod3$, then $I_S(p\bmod3;T_c)=1$.
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:sample}, Lemma~\ref{lem:unram} and Theorem~\ref{thm:onebit}.
\end{proof}

\begin{example}
For $c=7$ and $S=\{5,11,13,19\}$ the types are $1,1,0,3$, and $I_S=1$ exactly.
\end{example}

