\section{The Chebotarev model: $S_3$ acting on three roots}

For non-cube $c$, the splitting field $K_c$ of $x^3-c$ has Galois group $S_3$ and quadratic subfield $\Q(\sqrt{-3})$. For unramified $p$, the number of roots of $x^3-c$ mod $p$ equals $\#\Fix(\mathrm{Frob}_p)$, and $\sgn(\mathrm{Frob}_p)=+1$ iff $p\equiv1\pmod3$. By the Chebotarev density theorem, $\mathrm{Frob}_p$ is equidistributed with respect to class size. This motivates the model: $\sigma$ uniform on $S_3$. The results below are exact statements about $S_3$.

\begin{lemma}\label{lem:signfix}
For $\sigma\in S_3$: $\sgn\sigma=-1$ if $\#\Fix\sigma=1$, and $\sgn\sigma=+1$ otherwise.
\end{lemma}
\begin{proof}
The identity has $3$ fixed points and is even; transpositions have $1$ and are odd; $3$-cycles have $0$ and are even.
\end{proof}

\begin{theorem}[One bit in the model]\label{thm:s3}
For $\sigma$ uniform on $S_3$, $I(\sgn\sigma;\#\Fix\sigma)=1$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:signfix} and Theorem~\ref{thm:pin}, $I=H(\sgn)$, which equals $1$ by Theorem~\ref{thm:onebit}, since there are three even and three odd permutations.
\end{proof}

\begin{theorem}[Type entropy and refinement gap]\label{thm:gap}
For $\sigma$ uniform on $S_3$,
\[
H(\#\Fix)=\frac23+\frac{\log_23}{2}\approx1.4591,\qquad H(\#\Fix)-I(\sgn;\#\Fix)=\frac{\log_23}{2}-\frac13>\frac5{12}.
\]
\end{theorem}
\begin{proof}
The values $3,1,0$ occur with probabilities $\tfrac16,\tfrac12,\tfrac13$, so
$H=\tfrac16\log_26+\tfrac12+\tfrac13\log_23=\tfrac23+\tfrac12\log_23$. From $2^3<3^2$ we get $\log_23>\tfrac32$, so the gap exceeds $\tfrac34-\tfrac13=\tfrac5{12}$.
\end{proof}

\section{Chebotarev in the constant aspect}

\begin{theorem}\label{thm:const}
If $3\mid q-1$, then $3\cdot\#\{c\in\F_q^\times:\#R_3(c)=3\}=q-1$ and $3\cdot\#\{c\in\F_q^\times:\#R_3(c)=0\}=2(q-1)$.
\end{theorem}
\begin{proof}
$\sum_{c\ne0}\#R_3(c)=q-1$, since each $x\ne0$ lies in exactly one $R_3(x^3)$. Each summand is $0$ or $3$ by Proposition~\ref{prop:split}. The split and inert sets partition $\F_q^\times$.
\end{proof}

The ratio $1:2$ is that of the identity to the two $3$-cycles in $A_3$.

\section{Every prime exponent}

\begin{theorem}[Kummer type-channel law]\label{thm:kummer}
For $\ell$ prime and $c\in\F_q^\times$: $\#R_\ell(c)=1\iff\ell\nmid q-1$.
\end{theorem}
\begin{proof}
As in Theorem~\ref{thm:field}. If $\ell\mid q-1$ there are $\ell$ roots of unity of order dividing $\ell$, so the count is $0$ or $\ell$. Otherwise the $\ell$-th power map is bijective.
\end{proof}

\begin{proposition}[$\ell=5$ does not pin the residue]
$x^5=2$ has exactly one solution in $\F_7$ and in $\F_{13}$, yet $7\not\equiv13\pmod5$.
\end{proposition}

The type detects only $[p\equiv1\pmod\ell]$, which is all of $p\bmod\ell$ only when $\ell-1=2$, i.e.\ $\ell=3$.

\section{Boundaries of the law}\label{sec:boundaries}

\begin{proposition}[Ramified primes]
$T_7(7)=1$ (root $0$) though $7\equiv1\pmod3$, and $T_7(3)=1$ (since $x^3-7\equiv(x-1)^3$) though $3\equiv0\pmod3$.
\end{proposition}

\begin{proposition}[Non-pure $S_3$ cubics]
$x^3-x-1$ (discriminant $-23$) has exactly one root in $\F_5$ (namely $2$) and exactly one in $\F_7$ (namely $5$), yet $5\equiv2$ and $7\equiv1\pmod3$.
\end{proposition}

\begin{remark}
The underlying invariant is the Frobenius sign $(\disc f/p)$. For pure cubics $\disc=-27c^2$, so $(\disc/p)=(-3/p)$, which is determined by $p\bmod3$. As a numerical check, for $x^3-x-1$ and primes $p<500$, $p\ne2,23$, one root occurs exactly when $(-23/p)=-1$. This agrees with Stickelberger's classical parity theorem, which is not used here.
\end{remark}

\section{Algorithms}
\emph{Type channel.} Sieve the primes $p<N$ and discard $p\mid 3c$. If $p\equiv2\pmod3$, set $T_c(p)=1$. Otherwise set $T_c(p)=3$ if $c^{(p-1)/3}\equiv1\pmod p$ and $T_c(p)=0$ if not. This costs $O(\log p)$ multiplications per prime.

\emph{Empirical information.} Tabulate the counts of $f$, $g$ and $(f,g)$, and return $H(f)+H(g)-H(f,g)$, in $O(\#S)$ time.

\emph{Exact model.} Enumerate $S_3$ and apply the previous step.

\section{Discussion and future work}
The four experiments agreed because they measured a consequence of one fact: cubing is bijective on $\F_p^\times$ iff $3\nmid p-1$. Entropy invariance under injective relabelling converts this into the identity $I=H(p\bmod3)$ on every sample. The value is exactly $1$ bit only on balanced samples. By Dirichlet's theorem, $H(p\bmod3)\to1$ along the primes.

\begin{conjecture}[Discriminant sign law]
For separable cubic $f\in\Z[x]$ and $p\nmid 2\disc f$: $f$ has exactly one root mod $p$ iff $(\disc f/p)=-1$. Hence $I((\disc/p);T)=H((\disc/p))$ on every unramified sample.
\end{conjecture}

\begin{conjecture}[Kummer channel capacity]
For $x^\ell-c$, $\ell$ prime, the model information is $I(p\bmod\ell;T)=h(1/(\ell-1))<\log_2(\ell-1)$ for $\ell\ge5$.
\end{conjecture}

\begin{conjecture}[Constant aspect]
For $q\equiv1\pmod 3$ and $c$ uniform in $\F_q^\times$, $H(T)=h(1/3)=\log_23-\tfrac23$.
\end{conjecture}

For $S_4$ quartics, the zero-root type merges the odd $4$-cycles with the even double transpositions, so the root count no longer fully determines the Frobenius sign. Quantifying the resulting information deficit is left open.

\section{Conclusion}
For every pure cubic $x^3-c$ and every finite sample of unramified primes, $I(p\bmod3;T_c)=H(p\bmod3)$. The fourth field $x^3-7$ is one instance of this universal law. The value is exactly one bit on balanced samples and in the $S_3$ model. The type strictly refines the residue, and the law fails exactly where group theory predicts.

