from typing import List

def primes_below(n: int) -> List[int]:
    sieve = bytearray([1]) * max(n, 2)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytearray(len(range(i * i, n, i)))
    return [i for i in range(n) if sieve[i]]

def cube_type_fast(c: int, p: int) -> int:
    """Number of solutions of x^3 = c in F_p, for a prime p not dividing 3c.
    Uses the field-level law: one root iff p = 2 (mod 3); otherwise 3 or 0
    according as c is a cube, decided by the cubic Euler criterion c^((p-1)/3) = 1."""
    if p % 3 == 2:
        return 1
    return 3 if pow(c % p, (p - 1) // 3, p) == 1 else 0

def cube_type_brute(c: int, p: int) -> int:
    return sum(1 for x in range(p) if (x * x * x - c) % p == 0)

def type_decode(t: int) -> int:
    """Universal decoder: T = 1 -> residue 2, T in {0, 3} -> residue 1."""
    return 2 if t == 1 else 1

if __name__ == "__main__":
    for c in (2, 3, 5, 7):
        ps = [p for p in primes_below(3000) if (3 * c) % p != 0]
        assert all(cube_type_fast(c, p) == cube_type_brute(c, p) for p in ps[:150])
        fails = sum(type_decode(cube_type_fast(c, p)) != p % 3 for p in ps)
        print(f"c = {c}: {len(ps)} unramified primes < 3000, decoder failures = {fails}")

import math
from collections import Counter
from typing import Callable, Hashable, Sequence

def entropy(sample: Sequence[Hashable], f: Callable[[Hashable], Hashable]) -> float:
    n = len(sample)
    return -sum((k / n) * math.log2(k / n) for k in Counter(map(f, sample)).values())

def mutual_information(sample: Sequence[Hashable],
                       f: Callable[[Hashable], Hashable],
                       g: Callable[[Hashable], Hashable]) -> float:
    """I(f;g) = H(f) + H(g) - H(f,g) under the uniform distribution on the sample."""
    return entropy(sample, f) + entropy(sample, g) - entropy(sample, lambda a: (f(a), g(a)))

def factors_through(sample: Sequence[Hashable],
                    f: Callable[[Hashable], Hashable],
                    g: Callable[[Hashable], Hashable]) -> bool:
    """True iff f is a function of g on the sample (then I(f;g) = H(f) exactly)."""
    seen: dict = {}
    for a in sample:
        if seen.setdefault(g(a), f(a)) != f(a):
            return False
    return True

if __name__ == "__main__":
    cube = lambda c, p: sum(1 for x in range(p) if (x ** 3 - c) % p == 0)
    ps = [p for p in range(5, 1000) if all(p % d for d in range(2, int(p ** .5) + 1)) and p != 7]
    f = lambda p: p % 3
    g = lambda p: cube(7, p)
    print("factors through:", factors_through(ps, f, g))
    print("H(p mod 3) =", entropy(ps, f), " I =", mutual_information(ps, f, g))
    print("balanced {5,11,13,19}: I =", mutual_information([5, 11, 13, 19], f, g))

