import itertools
import math
from collections import Counter
from typing import Dict, List, Tuple

Perm = Tuple[int, ...]

def sign(s: Perm) -> int:
    inv = sum(1 for i, j in itertools.combinations(range(len(s)), 2) if s[i] > s[j])
    return -1 if inv % 2 else 1

def fix_count(s: Perm) -> int:
    return sum(1 for i, v in enumerate(s) if i == v)

def H(counts: List[int]) -> float:
    n = sum(counts)
    return -sum(k / n * math.log2(k / n) for k in counts if k)

def chebotarev_model(n: int) -> Dict[str, float]:
    """Exact entropies for sigma uniform in S_n: sign versus number of fixed points."""
    perms: List[Perm] = list(itertools.permutations(range(n)))
    hs = H(list(Counter(map(sign, perms)).values()))
    hf = H(list(Counter(map(fix_count, perms)).values()))
    hj = H(list(Counter((sign(s), fix_count(s)) for s in perms).values()))
    return {"H(sign)": hs, "H(#Fix)": hf, "I(sign;#Fix)": hs + hf - hj, "gap": hf - (hs + hf - hj)}

if __name__ == "__main__":
    m3 = chebotarev_model(3)
    print("S3:", m3)
    print("closed form H(#Fix) = 2/3 + log2(3)/2 =", 2 / 3 + math.log2(3) / 2)
    print("S4 (the sign is no longer determined by #Fix):", chebotarev_model(4))
